"""Utils module."""

import logging
from pathlib import Path
from typing import List, Generic, TypeVar, Union
from abc import ABC, abstractmethod
from uuid import uuid4
from taf.analyzer.pcap import pcap
from taf.analyzer.pcap.pcap_packet import PcapPacket


PACKET = TypeVar('PACKET')


class AbstractPcapProvider(Generic[PACKET], ABC):
    """Interface of pcap analyzer."""

    @abstractmethod
    def setup(self, infile: str, display_filter: str) -> 'AbstractPcapProvider':
        """Signature of method to initialize pcap analyzer with given file and packet filter."""

    @abstractmethod
    def get_packets(self) -> List[PACKET]:
        """Signature of method to return list of packets from filtered pcap file."""


class PcapProvider(AbstractPcapProvider[PcapPacket]):
    """Creates instance to filter pcap."""

    def __init__(self) -> None:
        self.uid = f'pcap_analyzer_{uuid4().hex}'
        self._pcap = pcap()

        logging.debug('%s PCAP provider was created.', self.uid)

    def setup(self, infile: Union[str, Path], display_filter: str) -> 'PcapProvider':
        """Initializes pcap analyzer with given file and packet filter."""

        self._pcap.setup(infile=str(infile), display_filter=display_filter, alias=self.uid)
        logging.debug('%s PCAP provider was initialized with %s file and %s filter.', self.uid, infile, display_filter)

        return self

    def get_packets(self) -> List[PACKET]:
        """Returns list of packets from filtered pcap file."""

        return self._pcap.get_packets(pcap_parser=self.uid)
